/**
 * @file
 * @brief Public ztest header
 */

#ifndef ZEPHYR_INCLUDE_ZTEST_ZTEST_TEST_H_
#define ZEPHYR_INCLUDE_ZTEST_ZTEST_TEST_H_

#include <zephyr/kernel.h>
#include <zephyr/sys/util.h>
#include <zephyr/toolchain.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

struct ztest_test_node {
	const char *name;
	void (*fn)(void);
	const char *suite_name;
#ifdef CONFIG_USERSPACE
	bool run_in_user_mode;
#endif
};

struct ztest_suite_node {
	const char *name;
	void (*setup)(void);
	void (*before)(void);
	void (*after)(void);
	void (*teardown)(void);
	struct ztest_test_node *test_list;
	size_t test_count;
};

#ifdef CONFIG_USERSPACE
#define ZTEST_USER_TEST_DECLARE(suite_name, test_name) \
	extern const bool ZTEST_USER_TEST_ ## suite_name ## _ ## test_name;
#define ZTEST_USER_TEST_DEFINE(suite_name, test_name) \
	const bool ZTEST_USER_TEST_ ## suite_name ## _ ## test_name = true;
#else
#define ZTEST_USER_TEST_DECLARE(suite_name, test_name)
#define ZTEST_USER_TEST_DEFINE(suite_name, test_name)
#endif

#define ZTEST_USER(...) \
	ZTEST_USER_TEST_DEFINE(__VA_ARGS__)

#define ZTEST_SUITE(suite_name, ...) \
	static void suite_name##_setup(void); \
	static void suite_name##_before(void); \
	static void suite_name##_after(void); \
	static void suite_name##_teardown(void); \
	extern struct ztest_test_node _CONCAT(ztest_tests_, suite_name)[]; \
	extern const size_t _CONCAT(ztest_tests_count_, suite_name); \
	static const struct ztest_suite_node __used \
	__attribute__((section(".ztest_suites"))) \
	_CONCAT(ztest_suite_, suite_name) = { \
		.name = #suite_name, \
		.setup = suite_name##_setup, \
		.before = suite_name##_before, \
		.after = suite_name##_after, \
		.teardown = suite_name##_teardown, \
		.test_list = _CONCAT(ztest_tests_, suite_name), \
		.test_count = _CONCAT(ztest_tests_count_, suite_name), \
	}; \
	static void suite_name##_setup(void) { } \
	static void suite_name##_before(void) { } \
	static void suite_name##_after(void) { } \
	static void suite_name##_teardown(void) { } \
	BUILD_ASSERT(true, "ZTEST_SUITE must be followed by ZTEST_TEST or ZTEST_F_TEST"); \
	__VA_ARGS__

#define ZTEST_TEST(suite_name, test_name) \
	static void test_name(void); \
	static const struct ztest_test_node __used \
	__attribute__((section(".ztest_tests"))) \
	_CONCAT(ztest_test_, test_name) = { \
		.name = #test_name, \
		.fn = test_name, \
		.suite_name = #suite_name \
		__DEBRACKET(COND_CODE_1(CONFIG_USERSPACE, \
			(,.run_in_user_mode = ZTEST_USER_TEST_ ## suite_name ## _ ## test_name), \
			())) \
	};

#define ZTEST_F_TEST(suite_name, test_name) \
	static void test_name(void *data); \
	static const struct ztest_test_node __used \
	__attribute__((section(".ztest_tests"))) \
	_CONCAT(ztest_test_, test_name) = { \
		.name = #test_name, \
		.fn = (void (*)(void))test_name, \
		.suite_name = #suite_name \
		__DEBRACKET(COND_CODE_1(CONFIG_USERSPACE, \
			(,.run_in_user_mode = ZTEST_USER_TEST_ ## suite_name ## _ ## test_name), \
			())) \
	};

#define ZTEST_DMEM __attribute__((section(".ztest_dmem")))
#define ZTEST_BMEM __attribute__((section(".ztest_bmem")))

#ifdef __cplusplus
}
#endif

#endif /* ZEPHYR_INCLUDE_ZTEST_ZTEST_TEST_H_ */
